import{_ as s,o as n,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const r=JSON.parse('{"title":"6. 编译、链接和执行","description":"The Little Book of C 中文版 — 6. 编译、链接和执行","frontmatter":{"title":"6. 编译、链接和执行","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","01-入门","中文"],"description":"The Little Book of C 中文版 — 6. 编译、链接和执行","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":6,"sidebarWeight":6,"alternateZh":"/posts/c教程/zh-CN/01-入门/006-Compiling, Linking, and Executing","alternateEn":"/posts/c教程/en-US/01-Getting Started/006-Compiling, Linking, and Executing"},"headers":[],"relativePath":"posts/c教程/zh-CN/01-入门/006-Compiling, Linking, and Executing.md","filePath":"posts/c教程/zh-CN/01-入门/006-Compiling, Linking, and Executing.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/zh-CN/01-入门/006-Compiling, Linking, and Executing.md"};function t(l,a,o,c,d,h){return n(),e("div",null,[...a[0]||(a[0]=[p(`<p>[English version](/posts/c教程/en-US/01-Getting Started/006-Compiling, Linking, and Executing)</p><p>当您按 Enter 编译 C 程序时，幕后会发生很多事情。您的源代码在成为可运行的可执行文件之前会经历几个阶段。理解这些步骤至关重要，它将编译错误从神秘变成简单、可修复的线索。</p><h4 id="小代码" tabindex="-1">小代码 <a class="header-anchor" href="#小代码" aria-label="Permalink to &quot;小代码&quot;">​</a></h4><p>让我们从一个熟悉的程序开始：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Learning the C build process!\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>现在一步步编译并运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Step 1: Compile to object file</span></span>
<span class="line"><span>gcc -c hello.c -o hello.o</span></span>
<span class="line"><span># Step 2: Link object file into executable</span></span>
<span class="line"><span>gcc hello.o -o hello</span></span>
<span class="line"><span># Step 3: Run the program</span></span>
<span class="line"><span>./hello</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Learning the C build process!</span></span></code></pre></div><h4 id="构建-c-程序的四个阶段" tabindex="-1">构建 C 程序的四个阶段 <a class="header-anchor" href="#构建-c-程序的四个阶段" aria-label="Permalink to &quot;构建 C 程序的四个阶段&quot;">​</a></h4><p>预处理 预处理器处理所有以<code>#</code>。它扩展宏、包含标头并准备编译代码。检查命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -E hello.c | less</span></span></code></pre></div><p>编译 编译器将预处理后的代码翻译成汇编语言，然后翻译成目标代码。每个源文件（例如<code>hello.c</code>) 成为目标文件 (<code>hello.o</code>）。命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c hello.c</span></span></code></pre></div><p>链接 链接器将所有目标文件和库组合成一个最终的可执行文件。例如，<code>printf</code>来自C标准库（<code>libc</code>)，因此链接器将您的代码连接到它。命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc hello.o -o hello</span></span></code></pre></div><p>执行一旦链接，您的二进制文件（<code>hello</code>）由操作系统加载并由CPU执行。命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./hello</span></span></code></pre></div><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>C 使您可以控制此过程的每个阶段。大多数现代语言隐藏编译或链接，但在 C 中，这些步骤是透明且可配置的。当出现问题、缺少函数、未定义的符号或损坏的包含时，您将确切地知道要查看哪个阶段。</p><p>掌握构建过程也为更深层次的技能打开了大门：</p><ul><li>创建可重用的库（<code>.a</code>或者<code>.so</code>文件）</li><li>了解 Makefile 和构建自动化</li><li>使用符号和优化构建进行调试</li><li>编写可在任何地方干净编译的便携式程序</li></ul><p>每个系统程序员最终都会学会像编译器一样思考，这就是思考的开始。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><p>尝试单独编译：</p><p>创建两个文件：</p><p>主程序</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>void greet(void);</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    greet();</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>问候.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>void greet(void) {</span></span>
<span class="line"><span>    printf(&quot;Hello from another file!\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>然后编译并链接：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c main.c</span></span>
<span class="line"><span>gcc -c greet.c</span></span>
<span class="line"><span>gcc main.o greet.o -o greetprog</span></span>
<span class="line"><span>./greetprog</span></span></code></pre></div><p>尝试打破它：删除<code>void greet(void);</code>线路输入<code>main.c</code>并重新编译，看看编译器如何警告您有关隐式声明的信息。</p><p>观察阶段：添加标志，例如<code>-Wall -O2 -v</code>查看来自编译器和链接器的详细消息。</p><p>一旦了解了编译和链接，您就解锁了 C 最强大的部分之一，即能够准确控制软件的构建、组合和执行方式。</p>`,35)])])}const u=s(i,[["render",t]]);export{r as __pageData,u as default};
